        } else {
            if (!this.world.isRemote && passenger instanceof EntityPlayer && !(this.getControllingPassenger() instanceof EntityPlayer)) {
                this.riddenByEntities.add(0, passenger);
            } else {
                this.riddenByEntities.add(passenger);
