    /**
     * Marks a vertical column of blocks dirty, scheduling a render update.
     * <p>
     * Automatically swaps y1 and y2 if they are backwards.
     */
    public void markBlocksDirtyVertical(int x, int z, int y1, int y2) {
        if (y1 > y2) {
            int i = y2;
            y2 = y1;
            y1 = i;
