                        SMCLog.info("Custom texture: " + s1 + " = " + s3);
                        list.add(icustomtexture);
                    }
                }
            }
        }

        if (list.size() <= 0)
        {
            return null;
        }
        else
        {
            ICustomTexture[] aicustomtexture = list.toArray(new ICustomTexture[list.size()]);
            return aicustomtexture;
