            {
                s = StrUtils.replaceSuffix(s, "_n.png", ".png");
                i = 1;
            }
            else if (s.endsWith("_s.png"))
            {
                s = StrUtils.replaceSuffix(s, "_s.png", ".png");
                i = 2;
