    void setDefaultFont(String name, int size) {
//        println("BetterFonts loading font \"" + name + "\"");
        usedFonts.clear();
        usedFonts.add(new Font(name, Font.PLAIN, 72)); //size 1 > 72

        fontSize = size;
        setRenderingHints();
    }

